import pyomo.environ as pyo

DATA = {
    "projects": ["X", "Y"],
    "cost": {"X": 500, "Y": 700},
    "performance_coeff": {"X": 2, "Y": 3},
    "min_performance": 2000,
    "max_total_resources": 1500,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.PROJECTS = pyo.Set(initialize=d["projects"])

    model.resource = pyo.Var(
        model.PROJECTS,
        within=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["cost"][p] * m.resource[p] for p in m.PROJECTS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def performance_rule(m):
        return sum(
            d["performance_coeff"][p] * m.resource[p] for p in m.PROJECTS
        ) >= d["min_performance"]

    model.performance_constraint = pyo.Constraint(rule=performance_rule)

    def budget_rule(m):
        return sum(m.resource[p] for p in m.PROJECTS) <= d["max_total_resources"]

    model.budget_constraint = pyo.Constraint(rule=budget_rule)

    return model
